from vfxops.io import read_image
from vfxops.draw import gradient
from vfxops.color import grade
from vfxops.filter import gaussian_blur
from vfxops.merge import merge_over
from vfxops.file_sequence import FileSequence
import pathlib

def noop(val):
    return val

from pygraphrt2 import Requestable

class ReadVideo(Requestable):
    def __init__(self, path: pathlib.Path):
        self._seq = FileSequence.from_single_frame(path)

    def __call__(self, frame:int):
        frame_path = self._seq.get_path(frame)
        return read_image(frame_path)

class BlurVideo(Requestable):
    def __init__(self, video:'Video', size:float=0.0):
        self.video=video
        self.size = size

    def __call__(self, frame:int):
        img = self.video(frame)
        return gaussian_blur(img, self.size)

class FrameBlend(Requestable):
    def __init__(self, video, duration:int):
        self.video = video
        self.duration = duration

    def __call__(self, frame:int):
        img = self.video(frame)
        for i in range(self.duration):
            left = self.video(frame-i)
            right = self.video(frame+i)

            img = merge_over(img, merge_over(left, right, 0.5), 0.5)
        return img

class TimeOffset(Requestable):
    def __init__(self, video, offset:int=0):
        self.video = video
        self.offset = offset

    def __call__(self, frame:int):
        return self.video(frame+self.offset)

class MergeVideo(Requestable):
    def __init__(self, A, B, mix:float=0.5):
        self.A = A
        self.B = B
        self.mix = mix

    def __call__(self, frame:int):
        imgA = self.A(frame)
        imgB = self.B(frame)
        return merge_over(imgA, imgB, self.mix)

def read_video(path: pathlib.Path):
    seq = FileSequence.from_single_frame(path)

    def wrapped(frame:int):
        frame_path = seq.get_path(frame)
        return read_image(frame_path)
    return wrapped

def blur_video(video, size:float=0.0):
    def wrapped(frame:int):
        img = video(frame)
        return gaussian_blur(img, size)
    return wrapped

def time_offset(video, offset:int=0):
    def wrapper(frame):
        return video(frame+offset)
    return wrapper

def merge_video(A, B, mix:float=0.5):
    def wrapper(frame:int):
        imgA = A(frame)
        imgB = B(frame)
        return merge_over(imgA, imgB, mix)
    return wrapper

def get_image_frame(video, frame:int=0):
    return video(frame)

__all__ = [
    'time_offset',
    'noop',
    'read_video',
    'blur_video',
    'get_image_frame',
    'merge_video',
    'read_image',
    'grade',
    'gradient',
    'gaussian_blur',
    'ReadVideo',
    'BlurVideo',
    'TimeOffset',
    'MergeVideo',
    'FrameBlend'
]
